def transform(grid):
 h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
 seeds=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==2]
 seen=set(seeds); stack=seeds[:]
 offsets=[(dr,dc) for dr in range(-2,3) for dc in range(-2,3) if 0<abs(dr)+abs(dc)<=2]
 while stack:
  r,c=stack.pop()
  for dr,dc in offsets:
   a,b=r+dr,c+dc
   if 0<=a<h and 0<=b<w and grid[a][b]!=0 and (a,b) not in seen:
    seen.add((a,b)); stack.append((a,b))
 for r,c in seen: out[r][c]=0 if grid[r][c]==2 else 2
 return out

